/* ═══ FLEET REGISTRY ═══════════════════════════════════════════════
   To add a cruise line: add the Excel sheet, then add ONE entry here
   keyed by the org slug the parser emits (auto-slugified from sheet name).
   buildOmbre() generates the seamless graduate-to-white atom gradient
   from a single hex base color, so a new fleet needs only base + hexInt.
   Fleets present in the data but missing here fall back to a neutral teal.
   ═══════════════════════════════════════════════════════════════════ */
const hexToRgb=(h)=>{const n=parseInt(h.replace("#",""),16);return[(n>>16)&255,(n>>8)&255,n&255];};
const mix=(a,b,t)=>a.map((v,i)=>Math.round(v+(b[i]-v)*t));
const rgbHex=(c)=>"#"+c.map(v=>v.toString(16).padStart(2,"0")).join("");
const buildOmbre=(base)=>{
  const b=hexToRgb(base);const white=[255,255,255];const black=mix(b,[0,0,0],0.85);
  const stops=[[black,0],[mix(black,b,0.4),8],[mix(black,b,0.7),15],[b,22],[mix(b,white,0.2),28],[mix(b,white,0.4),33],[mix(b,white,0.58),38],[mix(b,white,0.72),42],[mix(b,white,0.85),46],[mix(b,white,0.92),50],[mix(b,white,0.96),54],[white,62],[white,100]];
  return"radial-gradient(ellipse at center, "+stops.map(([c,p])=>`${rgbHex(c)} ${p}%`).join(", ")+")";
};
const FLEET_CONFIG={
  rc:{label:"ROYAL CARIBBEAN",base:"#1e3a8a",diamond:{main:0x1e3a8a,emissive:0x2563EB,glow:0x3B82F6,wire:0x60A5FA}},
  carnival:{label:"CARNIVAL",base:"#991b1b",diamond:{main:0x991b1b,emissive:0xDC2626,glow:0xEF4444,wire:0xFCA5A5}},
  ncl:{label:"NORWEGIAN",base:"#0784BD",diamond:{main:0x0784BD,emissive:0x0EA5E9,glow:0x38BDF8,wire:0x7DD3FC}},
};
// Palette for any fleet added later without an explicit config entry.
const FLEET_FALLBACK_PALETTE=["#7C3AED","#0891B2","#CA8A04","#BE185D","#15803D","#C2410C","#4338CA","#0F766E"];
const buildOrgs=(cands)=>{
  const slugs=[...new Set(cands.map(c=>c.org))];
  // Order cruise lines alphabetically by display label (EFFY always first).
  const labelFor=(slug)=>{const cfg=FLEET_CONFIG[slug];return cfg?cfg.label:slug.toUpperCase();};
  slugs.sort((a,b)=>labelFor(a).localeCompare(labelFor(b)));
  const orgs=[{id:"effy",label:"EFFY",base:"#0F766E",accent:C.teal,filter:()=>true,
    ombre:buildOmbre("#0F766E"),diamondColor:{main:0x0F766E,emissive:0x0F766E,glow:0x14B8A6,wire:0x5AB3AC}}];
  let fb=0;
  slugs.forEach(slug=>{
    const cfg=FLEET_CONFIG[slug];
    const base=cfg?cfg.base:FLEET_FALLBACK_PALETTE[fb++%FLEET_FALLBACK_PALETTE.length];
    const label=cfg?cfg.label:slug.toUpperCase();
    const diamond=cfg?cfg.diamond:{main:parseInt(base.slice(1),16),emissive:parseInt(base.slice(1),16),glow:0xFFFFFF,wire:0xCCCCCC};
    orgs.push({id:slug,label,base,accent:base,filter:c=>c.org===slug,ombre:buildOmbre(base),diamondColor:diamond});
  });
  return orgs;
};
const avgAcc=(arr,field)=>arr.length?arr.reduce((a,c)=>a+(c.acc?.[field]||0),0)/arr.length:0;
const avgMtd=(arr,field)=>arr.length?arr.reduce((a,c)=>a+(c.mtd?.[field]||0),0)/arr.length:0;
const sumMtd=(arr,field)=>arr.reduce((a,c)=>a+(c.mtd?.[field]||0),0);
const wAvgMtdSP=(arr)=>{let g=0,b=0;arr.forEach(c=>{const m=c.mtd||{};g+=(m.gap||0);b+=((m.sd||0)-(m.gap||0));});return b?g/b*100:0;};
const wAvgMtdAUR=(arr)=>{let s=0,u=0;arr.forEach(c=>{const m=c.mtd||{};if(m.aur>0){s+=(m.sd||0);u+=(m.sd||0)/m.aur;}});return u?s/u:0;};

