/* ═══ COLOR GRADIENT ═══ */
const metricColor=(v,isPercent=true)=>{
  if(!isPercent){if(v<0)return C.red;if(v<500)return C.amber;if(v<2000)return C.yellow;if(v<5000)return C.greenLt;return C.greenDk;}
  if(v<=-50)return C.red;if(v<=-10)return"#E85D3A";if(v<0)return C.amber;if(v<10)return C.yellow;if(v<30)return C.greenLt;if(v<60)return C.green;return C.greenDk;
};
const barGrad=(v)=>{if(v<-25)return C.red;if(v<0)return`linear-gradient(90deg,${C.red},${C.amber})`;if(v<10)return`linear-gradient(90deg,${C.amber},${C.yellow})`;if(v<30)return`linear-gradient(90deg,${C.yellow},${C.greenLt})`;return`linear-gradient(90deg,${C.greenLt},${C.greenDk})`;};
/* Sales Vs Budget gradient: <0 red, 0-5 orange, 5-10 yellow, 10+ greens */
const spGrad=(v)=>{if(v<0)return C.red;if(v<5)return C.amber;if(v<10)return C.yellow;if(v<20)return`linear-gradient(90deg,${C.yellow},${C.greenLt})`;if(v<35)return C.greenLt;return`linear-gradient(90deg,${C.greenLt},${C.greenDk})`;};
const spColor=(v)=>{if(v<0)return C.red;if(v<5)return C.amber;if(v<10)return C.yellow;if(v<20)return C.greenLt;if(v<35)return C.green;return C.greenDk;};
/* AUR gradient: 0-1800 red, 1800-2400 yellow, 2400+ yellow into green */
const aurGrad=(v)=>{if(v<1800)return C.red;if(v<2400)return C.yellow;if(v<3200)return`linear-gradient(90deg,${C.yellow},${C.greenLt})`;return`linear-gradient(90deg,${C.greenLt},${C.greenDk})`;};
const aurColor=(v)=>{if(v<1800)return C.red;if(v<2400)return C.yellow;if(v<3200)return C.greenLt;return C.greenDk;};
/* Total Sales gradient: relative to fleet max. <25% red, 25-50 amber, 50-75 yellow, 75+ green */
const salesColorRel=(ratio)=>{if(ratio<0.25)return C.red;if(ratio<0.5)return C.amber;if(ratio<0.75)return C.yellow;if(ratio<0.9)return C.greenLt;return C.greenDk;};
const salesGradRel=(ratio)=>{if(ratio<0.25)return C.red;if(ratio<0.5)return`linear-gradient(90deg,${C.red},${C.amber})`;if(ratio<0.75)return`linear-gradient(90deg,${C.amber},${C.yellow})`;if(ratio<0.9)return`linear-gradient(90deg,${C.yellow},${C.greenLt})`;return`linear-gradient(90deg,${C.greenLt},${C.greenDk})`;};
const statusDot=(v)=>{const col=metricColor(v);return{width:8,height:8,borderRadius:"50%",background:col,boxShadow:`0 0 6px ${col}44`,display:"inline-block",flexShrink:0};};

/* ═══ INTELLIGENCE HELPERS (added: variance, forecast, confidence, digest, health) ═══ */
const intFmtK=(n)=>{const a=Math.abs(n||0);if(a>=1e6)return`$${(n/1e6).toFixed(2)}M`;if(a>=1e3)return`$${(n/1e3).toFixed(1)}K`;return`$${Math.round(n||0)}`;};
const intRevVoys=(c)=>(c.weekly||[]).filter(w=>!w.nb&&!w.nr);
const intSailedVoys=(c)=>(c.weekly||[]).filter(w=>!w.nb);
const intTierOf=(sp)=>sp>=20?"star":sp>=0?"growth":sp>=-25?"watch":"critical";
// budget reconstructed from sp: budget = sales / (1 + sp/100)
const intVoyBudget=(w)=>{if(w.nb)return 0;return (w.sd||0)-(w.gap||0);};
const intVariance=(c,scope)=>{
  let v=intSailedVoys(c);
  if(scope==="mtd")v=v.filter(w=>w.m===c.mtd.month);
  const sales=v.reduce((a,w)=>a+w.sd,0);
  const budget=v.reduce((a,w)=>a+intVoyBudget(w),0);
  return{sales,budget,variance:sales-budget};
};
const intConfidence=(n)=>n>=8?{label:"High confidence",color:C.green,level:3}:n>=4?{label:"Moderate confidence",color:C.amber,level:2}:{label:"Thin data",color:C.red,level:1};
/* Which KPI to push for the most impact toward a higher Sales vs Budget.
   Sales = Transactions x ATV, and ATV = AUR x UPT (UPT = Units/Transaction).
   Benchmarks are set per cruise line. We recommend the weakest lever, since
   that is where the most headroom (and therefore impact) sits. */
const FLEET_BENCHMARK={
  rc:{aur:2700,u:9.0,tr:7,upt:1.4},
  carnival:{aur:2200,u:6.0,tr:4,upt:1.4},
  ncl:{aur:2700,u:6.0,tr:5,upt:1.4},
};
const intDriver=(c,src)=>{
  const a=src||c.acc||{};
  const aur=a.aur||0,upt=a.upt||0,tr=a.tr||a.trAvg||0,u=a.u||a.uAvg||0;
  const BM=FLEET_BENCHMARK[c.org]||{aur:2400,u:6.0,tr:5,upt:1.4};
  const gap={
    AUR:Math.max(0,(BM.aur-aur)/BM.aur),
    Units:Math.max(0,(BM.u-u)/BM.u),
    Transactions:Math.max(0,(BM.tr-tr)/BM.tr),
  };
  let best="AUR",bestGap=-1;
  for(const k in gap){if(gap[k]>bestGap){bestGap=gap[k];best=k;}}
  if(bestGap<=0){
    // Already at or above every benchmark: the gap is volume/consistency, not a single lever.
    return{kpi:"Volume",detail:`AUR, units, and transactions all meet the ${(FLEET_BENCHMARK[c.org]?({rc:"Royal Caribbean",carnival:"Carnival",ncl:"Norwegian"}[c.org]):"fleet")} benchmark. Lift comes from more sales at this standard: drive consistency across more voyages.`};
  }
  const detail={
    AUR:`AUR is $${Math.round(aur).toLocaleString()} vs a $${BM.aur.toLocaleString()} target. Anchor higher-value pieces first.`,
    Units:`Units run ${u.toFixed(1)} per voyage vs ${BM.u.toFixed(1)}. Complete the story with companion pieces.`,
    Transactions:`Transactions run ${tr.toFixed(1)} per voyage vs ${BM.tr}. Drive more guest approaches and enrolments.`,
  };
  return{kpi:best,detail:detail[best]};
};
const intMonths=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const intForecast=(c)=>{
  const m=c.mtd.month;const mv=intSailedVoys(c).filter(w=>w.m===m);
  if(!mv.length)return null;
  const now=getESTNow();const mi=intMonths.indexOf(m);
  const yr=now.getFullYear();
  const dim=new Date(yr,mi+1,0).getDate();
  // If this is the live calendar month, project from days elapsed so far.
  // If the ambassador's latest month is already complete (past month), the
  // month is fully elapsed, so the projection equals the recorded actuals.
  const isLiveMonth=now.getMonth()===mi;
  const elapsed=isLiveMonth?Math.max(now.getDate(),1):dim;
  const sales=mv.reduce((a,w)=>a+w.sd,0);
  const budget=mv.reduce((a,w)=>a+intVoyBudget(w),0);
  const projSales=sales/elapsed*dim;
  const projSP=budget>0?((sales/budget-1)*100):null;
  return{projSales,projSP,elapsed,dim,isLiveMonth};
};
// Tuesday-over-Tuesday: synthesize prior snapshot by dropping each ambassador's most recent revenue voyage.
// In production this is replaced by diffing the two most recent stored uploads.
const intPrevSnap=(list)=>list.map(c=>{
  const rev=intSailedVoys(c);
  if(rev.length<2)return{name:c.name,prevSP:undefined};
  const prior=rev.slice(0,-1);
  const s=prior.reduce((a,w)=>a+w.sd,0),b=prior.reduce((a,w)=>a+intVoyBudget(w),0);
  const sp=b>0?Math.round((s/b-1)*1000)/10:c.acc.sp;
  return{name:c.name,prevSP:sp,prevTier:intTierOf(sp),prevVar:s-b};
});
const intMovers=(active)=>{
  const pm=Object.fromEntries(intPrevSnap(active).map(p=>[p.name,p]));
  return active.filter(c=>intSailedVoys(c).length>=2)
    .map(c=>{const p=pm[c.name];const was=p&&p.prevSP!==undefined?p.prevSP:c.acc.sp;const nowVar=intVariance(c,"overall").variance;const dVar=p&&p.prevVar!==undefined?nowVar-p.prevVar:0;return{c,delta:c.acc.sp-was,dVar,was,now:c.acc.sp};})
    .sort((a,b)=>b.delta-a.delta);
};
const intDigest=(active)=>{
  const pm=Object.fromEntries(intPrevSnap(active).map(p=>[p.name,p]));
  const rank={star:4,growth:3,watch:2,critical:1};
  const up=[],down=[];
  active.forEach(c=>{const p=pm[c.name];if(!p||p.prevSP===undefined)return;const dSP=c.acc.sp-p.prevSP;if(rank[c.tier]>rank[p.prevTier])up.push({c,from:p.prevTier,to:c.tier,dSP});else if(rank[c.tier]<rank[p.prevTier])down.push({c,from:p.prevTier,to:c.tier,dSP});});
  return{up,down};
};
// Data health: ONLY active ambassadors with the most recent week in metrics (wkAvg.isCurrent).
const intHealth=(list)=>{
  const issues=[];
  list.filter(c=>c.status==="Active"&&c.wkAvg&&c.wkAvg.isCurrent).forEach(c=>{
    const nb=(c.weekly||[]).filter(w=>w.nb).length;
    const rev=intRevVoys(c).length;
    if(nb>0)issues.push({name:c.name,kind:"No budget",detail:`${nb} voyage${nb>1?"s":""} missing a budget figure`,sev:2});
    if(rev<3)issues.push({name:c.name,kind:"Thin sample",detail:`Only ${rev} revenue voyage${rev===1?"":"s"} in current contract`,sev:1});
    const r=intRevVoys(c);
    for(let i=1;i<r.length;i++){if(r[i-1].sd>2000&&r[i].sd<r[i-1].sd*0.15){issues.push({name:c.name,kind:"Sharp drop",detail:`Sales fell from ${intFmtK(r[i-1].sd)} to ${intFmtK(r[i].sd)} between voyages`,sev:2});break;}}
  });
  return issues.sort((a,b)=>b.sev-a.sev);
};
function loadJsPDF(){
  return new Promise((resolve,reject)=>{
    if(window.jspdf&&window.jspdf.jsPDF)return resolve(window.jspdf.jsPDF);
    const s=document.createElement("script");
    s.src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
    s.onload=()=>resolve(window.jspdf&&window.jspdf.jsPDF);
    s.onerror=()=>reject(new Error("pdf library unavailable"));
    document.head.appendChild(s);
  });
}
function deliverPDF(doc,fname){
  try{doc.save(fname);return true;}catch(e){}
  try{const blob=doc.output("blob");const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=fname;a.rel="noopener";document.body.appendChild(a);a.click();setTimeout(()=>{try{document.body.removeChild(a);}catch(_){}URL.revokeObjectURL(url);},1500);return true;}catch(e){}
  try{const url=doc.output("bloburl");const w=window.open(url,"_blank");if(w)return true;}catch(e){}
  try{doc.output("dataurlnewwindow");return true;}catch(e){}
  return false;
}
