function MetricCell({label,value,suffix="%",isDollar=false}){
  const col=isDollar?metricColor(value,false):metricColor(value);
  return(<div style={{textAlign:"center"}}><div style={{fontSize:17,fontWeight:700,color:col,fontFamily:"'Cormorant Garamond',serif"}}>{isDollar?"$":""}{value>0&&!isDollar?"+":""}{typeof value==="number"?isDollar?Math.round(value).toLocaleString():value.toFixed(1):value}{!isDollar?suffix:""}</div>{label&&<div style={{fontSize:8,color:C.dim,letterSpacing:1.2,fontWeight:600,marginTop:1}}>{label}</div>}</div>);
}

