    const schedHide=()=>{if(hideTimeoutRef.current)clearTimeout(hideTimeoutRef.current);hideTimeoutRef.current=setTimeout(()=>{if(!mouseRef.current.overTooltip){if(tooltipRef.current){tooltipRef.current.style.opacity="0";tooltipRef.current.style.pointerEvents="none";}if(hoveredRef.current){hoveredRef.current.material.emissiveIntensity=hoveredRef.current.userData.baseEmissive;hoveredRef.current.scale.setScalar(1);hoveredRef.current=null;}}},250);};
