    const onDn=(e)=>{if(mouseRef.current.overTooltip)return;mouseRef.current.down=true;const{x,y}=getMP(e);mouseRef.current.x=x;mouseRef.current.y=y;mouseRef.current.startX=x;mouseRef.current.startY=y;};
    const onUp=(e)=>{if(mouseRef.current.down){const{x,y}=getMP(e);if(Math.hypot(x-mouseRef.current.startX,y-mouseRef.current.startY)<5){const hits=doRC(x,y);if(hits.length>0&&hits[0].object.userData.candidate)onSelect(hits[0].object.userData.candidate);}}mouseRef.current.down=false;};
    const onLv=()=>{mouseRef.current.down=false;schedHide();};
    el.addEventListener("mousemove",onMv);el.addEventListener("mousedown",onDn);el.addEventListener("mouseup",onUp);el.addEventListener("mouseleave",onLv);
    let t=0;const animate=()=>{frameRef.current=requestAnimationFrame(animate);t+=0.012;coreObj.rotation.y+=0.008;coreObj.rotation.x=Math.sin(t*0.35)*0.12;if(aura)aura.scale.setScalar(1+Math.sin(t*0.7)*0.08);if(iLight)iLight.intensity=1.3+Math.sin(t*2.5)*0.5;protons.forEach(p=>{p.userData.angle+=0.02*p.userData.speed;const a=p.userData.angle,r=p.userData.radius;p.position.set(Math.cos(a)*r*Math.cos(p.userData.axisX),Math.sin(a)*r*Math.sin(p.userData.axisZ+0.5),Math.sin(a)*r*Math.cos(p.userData.axisZ));});ptCore.intensity=1.2+Math.sin(t*3)*0.4;scene.children.forEach(child=>{if(child.userData?.tierKey){child.children.forEach(obj=>{if(obj.userData?.candidate){const ud=obj.userData;const an=ud.baseAngle+t*ud.orbitSpeed;obj.position.set(Math.cos(an)*ud.orbitRadius,Math.sin(t*1.5+ud.baseAngle)*0.15,Math.sin(an)*ud.orbitRadius);if(ud.label)ud.label.position.copy(obj.position);}});}});if(!mouseRef.current.down)mouseRef.current.camTheta+=0.001;const cd=16,ph=mouseRef.current.camPhi,th=mouseRef.current.camTheta;camera.position.set(Math.sin(th)*Math.cos(ph)*cd,Math.sin(ph)*cd,Math.cos(th)*Math.cos(ph)*cd);camera.lookAt(0,0,0);renderer.render(scene,camera);};animate();
    const onResize=()=>{const nw=el.clientWidth;if(nw>0){camera.aspect=nw/h;camera.updateProjectionMatrix();renderer.setSize(nw,h);}};window.addEventListener("resize",onResize);
    let ro=null;if(typeof ResizeObserver!=="undefined"){ro=new ResizeObserver(()=>{onResize();});ro.observe(el);}
